//It takes Claude's resume responses, parses and normalizes them into a consistent resume JSON structure, combines all resumes into one resumes array, and prepares them for the frontend response.
// Code node - "Run Once for All Items" mode
// Place this directly before your Respond to Webhook node.
// It normalizes every incoming item into the resume schema and
// returns them all as ONE array (required by the frontend).

const schema = {
  candidateName: "",
  contactInfo: { email: "", phone: "", location: "", linkedin: "", website: "" },
  professionalSummary: "",
  skillCategories: [],
  experience: [],
  education: [],
  certifications: [],
  projects: [],
  additionalSections: []
};

const results = [];

for (const item of $input.all()) {
  let rawText = item.json.content?.[0]?.text
             ?? item.json.output
             ?? item.json.text
             ?? item.json.data;

  // If this item is already a normalized object (e.g. ran through the
  // per-item Code node earlier), just use it directly instead of re-parsing.
  if (!rawText && item.json.candidateName) {
    results.push({ ...schema, ...item.json, contactInfo: { ...schema.contactInfo, ...(item.json.contactInfo || {}) } });
    continue;
  }

  if (!rawText) {
    throw new Error(
      `Could not find Claude response text on item ${results.length}. ` +
      `Check the field name — log item.json to inspect it.`
    );
  }

  rawText = rawText.trim();
  if (rawText.startsWith('```')) {
    rawText = rawText.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  }

  let resume;
  try {
    resume = JSON.parse(rawText);
  } catch (err) {
    throw new Error(
      `Failed to parse Claude's response as JSON for item ${results.length}. ` +
      `Raw text: ${rawText.substring(0, 300)}...`
    );
  }

  const normalized = { ...schema, ...resume };
  normalized.contactInfo = { ...schema.contactInfo, ...(resume.contactInfo || {}) };

  results.push(normalized);
}

// IMPORTANT: return ONE item whose json IS the array.
// n8n wraps this as [{ json: [...] }] internally, but when your
// Respond to Webhook node is set to return $json (or "First Incoming Item"),
// it will output the array itself as the HTTP response body.
return [{ json: { resumes: results } }];

//It takes the normalized resume data and converts each resume into a professionally formatted paragraph-based template with headers, skills, experience, projects, education, certifications, and contact details, ready to create a Google Doc/PDF.

const resumeSourceItem = $('Normalize Resume Output').item;
const resumesArray = Array.isArray(resumeSourceItem.json.resumes)
  ? resumeSourceItem.json.resumes
  : [resumeSourceItem.json];

// ---- Brand colors / constants ----
const HEADING_COLOR = '1F4E79';
const WHITE = 'FFFFFF';
const BODY_FONT = 'Calibri';
const CONTENT_WIDTH = 468; // total usable line width in points (matches your page margins)

function buildResumeParagraphs(resumeData) {
  const paragraphs = [];

  function addPara(runs, opts = {}) {
    paragraphs.push({
      style: opts.style || 'Normal',
      alignment: opts.alignment || 'justify',
      border: opts.border || false,
      borderColor: opts.borderColor || null,
      shading: opts.shading || null,
      spaceAfter: opts.spaceAfter || 0,
      spaceBefore: opts.spaceBefore || 0,
      keepWithNext: opts.keepWithNext || false,
      keepLinesTogether: opts.keepLinesTogether !== false,
      runs
    });
  }

  function run(text, o = {}) {
    return {
      text: String(text ?? ''),
      bold: o.bold || false,
      italic: o.italic || false,
      underline: o.underline || false,
      font: o.font || BODY_FONT,
      size: o.size || 11,
      color: o.color || null,
      link: o.link || null
    };
  }

  function addBlank() {
    addPara([run('')], { size: 6, alignment: 'left' });
  }

  function sectionHeader(title) {
    addPara([run(title, { bold: true, size: 12, color: HEADING_COLOR })], {
      border: true,
      borderColor: HEADING_COLOR,
      spaceAfter: 4,
      alignment: 'left'
    });
  }

  const AVG_CHAR_WIDTH_FACTOR = 0.5;
  const SPACE_WIDTH_FACTOR = 0.28;

  function estimateWidth(text, fontSize) {
    return text.length * fontSize * AVG_CHAR_WIDTH_FACTOR;
  }

  function addTitleDateLine(leftText, dateText, opts = {}) {
    const LEFT_SIZE = 11.5;
    const DATE_SIZE = 10.5;

    const leftWidth = estimateWidth(leftText, LEFT_SIZE);
    const dateWidth = estimateWidth(dateText, DATE_SIZE);
    const spaceWidth = ((LEFT_SIZE + DATE_SIZE) / 2) * SPACE_WIDTH_FACTOR;

    const availableWidth = CONTENT_WIDTH - leftWidth - dateWidth;
    const numSpaces = Math.max(3, Math.round(availableWidth / spaceWidth));

    addPara([
      run(leftText, { bold: true, size: LEFT_SIZE }),
      run(' '.repeat(numSpaces), { size: LEFT_SIZE }),
      run(dateText, { italic: true, size: DATE_SIZE })
    ], { alignment: 'left', keepWithNext: opts.keepWithNext || false });
  }

  function chainKeepTogether(startIndex) {
    for (let i = startIndex; i < paragraphs.length - 1; i++) {
      paragraphs[i].keepWithNext = true;
    }
  }

  // ================= HEADER (blue banner, white text) =================
  const HEADER_BG      = '1F4E79';
  const NAME_COLOR     = WHITE;
  const CRED_COLOR     = WHITE;
  const TAGLINE_COLOR  = WHITE;
  const CONTACT_COLOR  = WHITE;
  const LINK_COLOR     = WHITE;
  const HEADER_FONT    = 'Georgia';

  addPara([run('', { size: 4 })], { alignment: 'center', shading: HEADER_BG });

  addPara([run((resumeData.candidateName || '').toUpperCase(), {
    bold: true, size: 22, color: NAME_COLOR, font: HEADER_FONT
  })], { alignment: 'center', shading: HEADER_BG });

  if (resumeData.credentialsLine) {
    addPara([run(resumeData.credentialsLine, {
      italic: true, size: 11, color: CRED_COLOR, font: HEADER_FONT
    })], { alignment: 'center', shading: HEADER_BG });
  }

  if (resumeData.tagline) {
    addPara([run(resumeData.tagline, {
      bold: true, size: 12, color: TAGLINE_COLOR, font: HEADER_FONT
    })], { alignment: 'center', shading: HEADER_BG });
  }

  const c = resumeData.contactInfo || {};
  const contactRuns = [];
  const pieces = [];
  if (c.location) pieces.push({ text: c.location });
  if (c.phone) pieces.push({ text: c.phone });
  if (c.email) pieces.push({ text: c.email });
  if (c.linkedin) {
    const displayText = c.linkedin.replace(/^https?:\/\//, '');
    pieces.push({ text: displayText, link: c.linkedin });
  }
  pieces.forEach((p, i) => {
    if (i > 0) contactRuns.push(run(' • ', { size: 10, color: CONTACT_COLOR, font: HEADER_FONT }));
    contactRuns.push(run(p.text, {
      size: 10,
      link: p.link || null,
      underline: !!p.link,
      color: p.link ? LINK_COLOR : CONTACT_COLOR,
      font: HEADER_FONT
    }));
  });
  addPara(contactRuns, { alignment: 'center', shading: HEADER_BG });

  addPara([run('', { size: 4 })], { alignment: 'center', shading: HEADER_BG });
  addBlank();

  // ================= PROFESSIONAL SUMMARY =================
  if (resumeData.professionalSummary) {
    const blockStart = paragraphs.length;
    sectionHeader('PROFESSIONAL SUMMARY');
    addPara([run(resumeData.professionalSummary, { size: 11 })], { alignment: 'justify' });
    chainKeepTogether(blockStart);
    addBlank();
  }

  // ================= SKILLS =================
  if (resumeData.skillCategories?.length) {
    const blockStart = paragraphs.length;
    sectionHeader('TECHNICAL SKILLS');
    resumeData.skillCategories.forEach(cat => {
      const label = cat.categoryName || cat.category || cat.name || '';
      const items = (cat.items || cat.skills || []).join(', ');
      addPara([
        run(label + ': ', { bold: true, size: 11, color: HEADING_COLOR }),
        run(items, { size: 11 })
      ], { alignment: 'justify' });
    });
    chainKeepTogether(blockStart);
    addBlank();
  }

  // ================= EXPERIENCE =================
  if (resumeData.experience?.length) {
    sectionHeader('PROFESSIONAL EXPERIENCE');
    paragraphs[paragraphs.length - 1].keepWithNext = true;

    resumeData.experience.forEach(exp => {
      const entryStart = paragraphs.length;
      const titleLine = [exp.jobTitle, exp.employer].filter(Boolean).join('  —  ');
      const dates = [exp.startDate, exp.endDate].filter(Boolean).join(' – ');
      addTitleDateLine(titleLine + (exp.location ? `, ${exp.location}` : ''), dates);
      (exp.bullets || []).forEach(b =>
        addPara([run('•  ' + b, { size: 11 })], { alignment: 'justify' })
      );
      chainKeepTogether(entryStart);
      addBlank();
    });
  }

  // ================= PROJECTS =================
  if (resumeData.projects?.length) {
    sectionHeader('PROJECTS');
    paragraphs[paragraphs.length - 1].keepWithNext = true;

    resumeData.projects.forEach(p => {
      const entryStart = paragraphs.length;
      addPara([run(p.name || '', { bold: true, size: 11.5 })], { alignment: 'left' });
      if (p.description) {
        addPara([
          run('Tech Stack: ', { bold: true, italic: true, size: 10.5 }),
          run(p.description, { italic: true, size: 10.5 })
        ], { alignment: 'justify' });
      }
      (p.bullets || []).forEach(b =>
        addPara([run('•  ' + b, { size: 11 })], { alignment: 'justify' })
      );
      chainKeepTogether(entryStart);
      addBlank();
    });
  }

  // ================= EDUCATION =================
  if (resumeData.education?.length) {
    sectionHeader('EDUCATION');
    paragraphs[paragraphs.length - 1].keepWithNext = true;

    resumeData.education.forEach(ed => {
      const entryStart = paragraphs.length;
      const dates = [ed.startDate, ed.endDate].filter(Boolean).join(' – ');
      addTitleDateLine(ed.degree || '', dates);
      const instLine = [ed.institution, ed.location].filter(Boolean).join('  |  ');
      if (instLine) addPara([run(instLine, { size: 11 })], { alignment: 'left' });
      if (ed.details) addPara([run(ed.details, { size: 10.5 })], { alignment: 'justify' });
      chainKeepTogether(entryStart);
    });
    addBlank();
  }

  // ================= CERTIFICATIONS =================
  if (resumeData.certifications?.length) {
    const blockStart = paragraphs.length;
    sectionHeader('CERTIFICATIONS');
    resumeData.certifications.forEach(cert =>
      addPara([run('•  ' + (typeof cert === 'string' ? cert : (cert.name || '')), { size: 11 })], { alignment: 'justify' })
    );
    chainKeepTogether(blockStart);
    addBlank();
  }

  // ================= ADDITIONAL SECTIONS =================
  (resumeData.additionalSections || []).forEach(sec => {
    const blockStart = paragraphs.length;
    sectionHeader((sec.heading || '').toUpperCase());
    (sec.items || []).forEach(i =>
      addPara([run('•  ' + i, { size: 11 })], { alignment: 'justify' })
    );
    chainKeepTogether(blockStart);
    addBlank();
  });

  return paragraphs;
}

// ---- Build one output item per resume in the array ----
return resumesArray.map(resumeData => ({
  json: {
    resumeTemplate: buildResumeParagraphs(resumeData),
    candidateName: resumeData.candidateName || ''
  }
}));

//It converts each formatted resume template into Google Docs API requests (insert text + formatting instructions) so each resume can be automatically created as a properly formatted Google Doc.
// Process ALL items coming from "Code in JavaScript8" (one per resume)
const inputItems = $('Build Resume Document Template').all();

function decodeHtmlEntities(str = "") {
  return str
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, " ");
}

function hexToRgb(hex) {
  if (!hex) return null;
  const clean = hex.replace("#", "");
  if (clean.length !== 6) return null;
  const bigint = parseInt(clean, 16);
  return {
    red: ((bigint >> 16) & 255) / 255,
    green: ((bigint >> 8) & 255) / 255,
    blue: (bigint & 255) / 255,
  };
}

// Everything from your original script, wrapped in a function that
// takes a single resume's paragraphs and returns its own requests array.
function buildRequestsForResume(paragraphs) {
  const requests = [];
  let currentIndex = 1;

  for (const para of paragraphs) {
    if (!para.runs) continue;

    para.runs.forEach(r => { r.text = decodeHtmlEntities(r.text || ""); });
    const hasText = para.runs.some(r => r.text.trim().length);

    let paragraphText = "";
    const runRanges = [];
    for (const run of para.runs) {
      const start = currentIndex + paragraphText.length;
      paragraphText += run.text || "";
      const end = currentIndex + paragraphText.length;
      runRanges.push({ run, start, end });
    }
    paragraphText += "\n";

    requests.push({
      insertText: { location: { index: currentIndex }, text: paragraphText }
    });

    const paragraphStyle = {};
    const paragraphFields = ["namedStyleType"];
    paragraphStyle.namedStyleType = para.style === "Heading1" ? "HEADING_1" : "NORMAL_TEXT";

    if (para.alignment) {
      paragraphStyle.alignment =
        para.alignment === "center"  ? "CENTER" :
        para.alignment === "right"   ? "END" :
        para.alignment === "justify" ? "JUSTIFIED" :
        "START";
      paragraphFields.push("alignment");
    }

    if (typeof para.spaceAfter === "number") {
      paragraphStyle.spaceBelow = { magnitude: para.spaceAfter, unit: "PT" };
      paragraphFields.push("spaceBelow");
    }

    if (typeof para.spaceBefore === "number" && para.spaceBefore > 0) {
      paragraphStyle.spaceAbove = { magnitude: para.spaceBefore, unit: "PT" };
      paragraphFields.push("spaceAbove");
    }

    if (typeof para.lineSpacing === "number") {
      paragraphStyle.lineSpacing = para.lineSpacing;
      paragraphFields.push("lineSpacing");
    }

    if (typeof para.indentStart === "number") {
      paragraphStyle.indentStart = { magnitude: para.indentStart, unit: "PT" };
      paragraphFields.push("indentStart");
    }

    if (typeof para.indentEnd === "number") {
      paragraphStyle.indentEnd = { magnitude: para.indentEnd, unit: "PT" };
      paragraphFields.push("indentEnd");
    }

    if (typeof para.firstLineIndent === "number") {
      paragraphStyle.indentFirstLine = { magnitude: para.firstLineIndent, unit: "PT" };
      paragraphFields.push("indentFirstLine");
    }

    if (para.border) {
      paragraphStyle.borderBottom = {
        color: { color: { rgbColor: hexToRgb(para.borderColor || "#1F4E79") } },
        width: { magnitude: 1, unit: "PT" },
        padding: { magnitude: 2, unit: "PT" },
        dashStyle: "SOLID"
      };
      paragraphFields.push("borderBottom");
    }

    if (para.shading) {
      paragraphStyle.shading = { backgroundColor: { color: { rgbColor: hexToRgb(para.shading) } } };
      paragraphFields.push("shading");
    }

    if (para.keepWithNext) {
      paragraphStyle.keepWithNext = true;
      paragraphFields.push("keepWithNext");
    }

    if (para.keepLinesTogether) {
      paragraphStyle.keepLinesTogether = true;
      paragraphFields.push("keepLinesTogether");
    }

    requests.push({
      updateParagraphStyle: {
        range: { startIndex: currentIndex, endIndex: currentIndex + paragraphText.length },
        paragraphStyle,
        fields: paragraphFields.join(",")
      }
    });

    if (hasText) {
      for (const { run, start, end } of runRanges) {
        if (start >= end) continue;
        const textStyle = {};
        const textFields = [];
        if (run.bold) { textStyle.bold = true; textFields.push("bold"); }
        if (run.italic) { textStyle.italic = true; textFields.push("italic"); }
        if (run.underline) { textStyle.underline = true; textFields.push("underline"); }
        if (run.font) { textStyle.weightedFontFamily = { fontFamily: run.font }; textFields.push("weightedFontFamily"); }
        if (run.size) { textStyle.fontSize = { magnitude: run.size, unit: "PT" }; textFields.push("fontSize"); }
        if (run.color) {
          const rgb = hexToRgb(run.color);
          if (rgb) { textStyle.foregroundColor = { color: { rgbColor: rgb } }; textFields.push("foregroundColor"); }
        }
        if (run.link) { textStyle.link = { url: run.link }; textFields.push("link"); }
        if (textFields.length) {
          requests.push({
            updateTextStyle: { range: { startIndex: start, endIndex: end }, textStyle, fields: textFields.join(",") }
          });
        }
      }
    }

    currentIndex += paragraphText.length;
  }

  return requests;
}

// Build one output item per input item, preserving candidateName etc.
return inputItems.map(item => ({
  json: {
    requests: buildRequestsForResume(item.json.resumeTemplate),
    candidateName: item.json.candidateName || ''
  }
}));

//It parses and repairs the AI-generated cover letter JSON, converts it into Google Docs API formatting/insert requests, and prepares each cover letter to be created as a properly formatted Google Doc.
// ---------------------------------------------
// Strip code fences the model sometimes adds anyway
// ---------------------------------------------
function cleanText(rawText) {
  return rawText.trim()
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/```\s*$/i, "");
}

// ---------------------------------------------
// Best-effort repair for JSON truncated mid-string/mid-object.
// This is only a safety net — the real fix is raising max_tokens
// on the COVER LETTER node so truncation stops happening at the source.
// ---------------------------------------------
function attemptRepair(text) {
  let repaired = text;

  const quoteCount = (repaired.match(/(?<!\\)"/g) || []).length;
  if (quoteCount % 2 !== 0) {
    repaired += '"';
  }

  repaired = repaired.replace(/,\s*$/, "");

  const stack = [];
  for (const ch of repaired) {
    if (ch === "{" || ch === "[") stack.push(ch);
    else if (ch === "}" || ch === "]") stack.pop();
  }
  while (stack.length) {
    const open = stack.pop();
    repaired += open === "{" ? "}" : "]";
  }

  return repaired;
}

function parseCoverLetterJson(rawTextRaw) {
  const rawText = cleanText(rawTextRaw);
  try {
    return JSON.parse(rawText);
  } catch (firstErr) {
    try {
      return JSON.parse(attemptRepair(rawText));
    } catch (secondErr) {
      throw new Error(
        `Failed to parse cover letter JSON even after repair attempt: ${secondErr.message}. ` +
        `The AI node's response was truncated (raw length: ${rawText.length} chars). ` +
        `Fix: open the COVER LETTER node and increase its max_tokens setting to ` +
        `2000-3000, then re-run.`
      );
    }
  }
}

// ---------------------------------------------
// Build the Google Docs batchUpdate "requests" array
// for a single parsed cover letter object. Index/requests
// are local to each call so items never bleed into each other.
// ---------------------------------------------
function buildRequestsForCoverLetter(data) {
  let requests = [];
  let index = 1;

  function addText(text, options = {}) {
    text = text || "";
    const start = index;
    requests.push({
      insertText: {
        location: { index },
        text: text + "\n"
      }
    });
    index += text.length + 1;
    if (text.length > 0 && (options.fontSize || options.bold || options.fontFamily)) {
      requests.push({
        updateTextStyle: {
          range: {
            startIndex: start,
            endIndex: index - 1
          },
          textStyle: {
            bold: options.bold || false,
            weightedFontFamily: {
              fontFamily: options.fontFamily || "Times New Roman"
            },
            fontSize: {
              magnitude: options.fontSize || 11,
              unit: "PT"
            }
          },
          fields: "bold,weightedFontFamily,fontSize"
        }
      });
    }
    return start;
  }

  function addBlankLine() {
    addText("", { fontSize: 11 });
  }

  // ==========================
  // SENDER HEADER (candidate name + contact)
  // ==========================
  addText(data.candidateName || "", {
    bold: true,
    fontSize: 16
  });

  const contact = data.candidateContact || {};
  const contactLine = [contact.email, contact.phone, contact.location]
    .filter(Boolean)
    .join("   |   ");
  addText(contactLine, { fontSize: 10 });

  addBlankLine();

  // ==========================
  // DATE
  // ==========================
  if (data.date) {
    addText(data.date, { fontSize: 11 });
    addBlankLine();
  }

  // ==========================
  // RECIPIENT / ROLE REFERENCE
  // ==========================
  if (data.companyName) {
    addText(data.companyName, { fontSize: 11 });
  }
  if (data.jobTitle) {
    addText(`Re: Application for ${data.jobTitle}`, {
      fontSize: 11,
      bold: true
    });
  }

  addBlankLine();

  // ==========================
  // SALUTATION
  // ==========================
  addText(data.salutation || "Dear Hiring Manager,", {
    fontSize: 11
  });

  addBlankLine();

  // ==========================
  // BODY
  // ==========================
  if (data.openingParagraph) {
    addText(data.openingParagraph, { fontSize: 11 });
    addBlankLine();
  }

  for (const para of data.bodyParagraphs || []) {
    addText(para, { fontSize: 11 });
    addBlankLine();
  }

  if (data.closingParagraph) {
    addText(data.closingParagraph, { fontSize: 11 });
    addBlankLine();
  }

  // ==========================
  // SIGN OFF
  // ==========================
  addText(data.signOff || "Sincerely,", { fontSize: 11 });
  addBlankLine();
  addText(data.candidateName || "", { fontSize: 11 });

  return requests;
}

// ---------------------------------------------
// MAIN — process every input item, not just the first
// ---------------------------------------------
const allItems = $input.all();
const output = [];

for (let i = 0; i < allItems.length; i++) {
  const item = allItems[i].json;

  let rawText;
  try {
    rawText = item.content[0].text;
  } catch (e) {
    throw new Error(`Item ${i}: missing content[0].text in AI node output.`);
  }

  const data = parseCoverLetterJson(rawText);
  const requests = buildRequestsForCoverLetter(data);

  output.push({
    json: {
      requests,
      candidateName: data.candidateName || "",
      companyName: data.companyName || ""
    }
  });
}

return output;

//It combines each generated resume/cover-letter URL with the corresponding job's company name and job URL from the Webhook, then returns everything as one results array for the frontend.
const items = $input.all();
console.log('input items:', items);
console.log('first item json:', items[0]?.json);

const results = items.map((item, index) => {
  const match = $('Webhook').all()[index];
  console.log(`index ${index} ->`, match?.json?.company_name);

  return {
    ApplyLink: match?.json?.job_url ?? "",
    companyName: match?.json?.company_name ?? "",
    resumeUrl: item.json.resumeUrl ?? "",
    coverLetterUrl: item.json.coverUrl ?? ""
  };
});

return [{ json: { results } }];
